"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["86490"],{65354(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.impedimento_fora_da_inscricao","status":422,"titulo":"S\xf3 o formul\xe1rio de inscri\xe7\xe3o tem impedimento"},"descricao":{"codigo":"uniplus.item_formulario.impedimento_fora_da_inscricao","requisitos":[],"oQueAconteceu":["O impedimento \xe9 a resposta do campo que impede a inscri\xe7\xe3o do candidato, e a mensagem que o explica \xe9 a que o administrador define. Por isso s\xf3 o formul\xe1rio de inscri\xe7\xe3o o tem. Um item do formul\xe1rio de isen\xe7\xe3o de taxa ou de habilita\xe7\xe3o, ou de um modelo que n\xe3o serve \xe0 fase de inscri\xe7\xe3o, traz `impedimento`. A mensagem \xe9 \\"S\xf3 o formul\xe1rio de inscri\xe7\xe3o tem impedimento: ele impede a inscri\xe7\xe3o do candidato.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].impedimento`, uma entrada por item com impedimento; nos modelos de formul\xe1rio, `conteudo.itens[i].impedimento`. O campo de um grupo repet\xedvel com impedimento \xe9 outra recusa, a de [campo de grupo com impedimento](/erros/uniplus.grupo_formulario.campo_com_impedimento), em qualquer finalidade. Nada \xe9 gravado.","Na grava\xe7\xe3o dos itens do formul\xe1rio, a recusa vem depois da recusa de todas as outras causas dos itens e dos grupos: enquanto houver forma, cat\xe1logo ou sem\xe2ntica a corrigir, ela n\xe3o aparece, e s\xf3 passa a ser apontada quando o resto do pedido est\xe1 conforme. Nos modelos, ela sai junto com as recusas da forma dos itens. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Retire `impedimento` dos itens do formul\xe1rio que n\xe3o \xe9 o de inscri\xe7\xe3o. Se a resposta deve impedir a inscri\xe7\xe3o, declare o impedimento no item do formul\xe1rio de inscri\xe7\xe3o que coleta o fato."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);